
"""Output verification for responses generated by LLM providers."""

from dataclasses import dataclass

from backend.detectors.findings import SecurityFinding
from backend.detectors.pipeline import detect_sensitive_data
from backend.detectors.redaction import redact_sensitive_data
from backend.risk_scoring.scorer import calculate_risk


@dataclass(frozen=True)
class OutputVerificationResult:
    """Verified and sanitized LLM output."""

    content: str
    findings: tuple[SecurityFinding, ...]
    risk_score: float
    risk_level: str
    sanitized: bool


def verify_output(text: str) -> OutputVerificationResult:
    """
    Detect and redact sensitive information in generated output.

    Raises an exception if verification cannot be completed.
    The caller must not return the original output in that case.
    """

    if not isinstance(text, str):
        raise TypeError("LLM output must be a string.")

    if not text.strip():
        raise ValueError("LLM output must not be empty.")

    findings = detect_sensitive_data(text)

    redaction = redact_sensitive_data(text, findings)

    risk = calculate_risk(findings)

    return OutputVerificationResult(
        content=redaction.redacted_text,
        findings=tuple(findings),
        risk_score=risk.score,
        risk_level=risk.level,
        sanitized=redaction.redaction_count > 0,
    )
